-    var dirs = [NSHomeDirectory() + "/.config/ghostty/themes"]
-    if let bundled = Bundle.main.resourceURL?.appendingPathComponent("ghostty/themes").path {
-      dirs.append(bundled)
+    guard let bundled = bundledThemeDirectory() else { return [userThemeDirectory()] }
